import{fetchCohortJSON}from'./current-cohort-loader.js';
const controlView=new URL(location.href).searchParams.get('arm')==='control';
const $=id=>document.getElementById(id),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),labels={all:'First 1,000 · all splits',development:'Development',holdout:'Original holdout',holdout049:'Fresh holdout',holdout056:'Expansion holdout',grok075:'Grok 1,000'};let d,directory,page=25;
function plot(s,i){const c=s.curves.targeted[i],old=s.curves.previous[i],change=s.changes[i],x=n=>48+n/24*500,y=n=>230-n/s.models*200,line=(arm,key)=>s.curves[arm].map((p,i)=>(i?'L':'M')+x(p.budget)+','+y(p[key])).join(' ');return `<article class="feature"><h2>${h(labels[s.cohort])}</h2><div class="totals"><div><strong>${c.top} / ${s.models}</strong>Supported Top<br>${controlView?'':`<span>Control ${old.top} · ${c.top-old.top>=0?'+':''}${c.top-old.top}</span>`}</div><div><strong>${c.degree} / ${s.models}</strong>Bachelor / graduate Top<br>${controlView?'':`<span>Control ${old.degree} · ${c.degree-old.degree>=0?'+':''}${c.degree-old.degree}</span>`}</div></div><svg viewBox="0 0 580 275" style="width:100%" role="img" aria-label="${h(labels[s.cohort])} fresh coverage from zero to 24 follow-ups">${[0,.25,.5,.75,1].map(v=>`<line x1="48" x2="548" y1="${y(v*s.models)}" y2="${y(v*s.models)}" stroke="#ccd8cd"/><text x="5" y="${y(v*s.models)+4}" fill="currentColor" font-size="14">${v*100}%</text>`).join('')}${d.budgets.map(v=>`<text x="${x(v)}" y="253" text-anchor="middle" fill="currentColor" font-size="14">${v}</text>`).join('')}<path d="${line('targeted','top')}" fill="none" stroke="#22845d" stroke-width="3"/><path d="${line('targeted','degree')}" fill="none" stroke="#3269c4" stroke-width="3"/>${$('compare').checked?`<path d="${line('previous','top')}" fill="none" stroke="#22845d" stroke-dasharray="5 5"/><path d="${line('previous','degree')}" fill="none" stroke="#3269c4" stroke-dasharray="5 5"/>`:''}<line x1="${x(c.budget)}" x2="${x(c.budget)}" y1="20" y2="230" stroke="currentColor" opacity=".4"/></svg><p>${(c.asked/s.models).toFixed(1)} follow-ups/model actually asked ${controlView?'':`(control ${(old.asked/s.models).toFixed(1)})`} · ${(c.unknown/Math.max(1,c.asked)*100).toFixed(1)}% unknown.</p><details ${controlView?'hidden':''}><summary>Gains and losses</summary><p>Top: ${change.gainedTop} gained · ${change.lostTop} lost. Bachelor/graduate Top: ${change.gainedDegree} gained · ${change.lostDegree} lost.</p><p>Any supported bachelor / graduate option: ${c.allDegree}. Top is capped at three.</p></details></article>`;}
function render(){const bi=+$('budget').value,b=d.budgets[bi],cohort=$('cohort').value,s=d.summary.find(s=>s.cohort===cohort),g=d.summary.find(s=>s.cohort==='grok075');$('total').textContent=`Fresh start: 60 interest questions + up to ${b} selected follow-ups = up to ${60+b} interest questions. Lifestyle is separate. No accumulated exploration answers.`;$('plots').innerHTML=plot(s,bi)+plot(g,bi);$('splits').innerHTML=d.summary.filter(s=>!['all','grok075'].includes(s.cohort)).map(s=>`<p><b>${h(labels[s.cohort])} · ${s.models}:</b> ${s.curves.targeted[bi].top} Top · ${s.curves.targeted[bi].degree} bachelor / graduate Top. ${controlView?'':`Control: ${s.curves.previous[bi].top} / ${s.curves.previous[bi].degree}.`}</p>`).join('');
const query=$('search').value.toLowerCase(),issue=$('issue').value,group=$('group').value,rs=d.models.map((m,i)=>({m,p:directory.rows[i],cohort:d.cohorts[m[0]],top:!!(m[2]&(1<<bi)),degree:!!(m[3]&(1<<bi)),oldTop:!!(m[4]&(1<<bi)),oldDegree:!!(m[5]&(1<<bi))})).filter(r=>(r.cohort==='grok075'||(cohort==='all'?r.cohort!=='grok075':r.cohort===cohort))&&(group==='both'||group==='grok'&&r.cohort==='grok075'||group==='first'&&r.cohort!=='grok075')&&(!query||(r.p.id+' '+r.p.name).toLowerCase().includes(query))&&(issue==='all'||issue==='evaluable'&&r.m[1]||issue==='noTop'&&!r.top||issue==='noDegree'&&!r.degree||issue==='lostTop'&&r.oldTop&&!r.top||issue==='lostDegree'&&r.oldDegree&&!r.degree||issue==='gainedTop'&&!r.oldTop&&r.top));rs.sort((a,b)=>Number(b.top)-Number(a.top));$('count').textContent=`${rs.length} models · showing ${Math.min(page,rs.length)} · Supported Top first`;$('models').innerHTML=rs.slice(0,page).map(r=>{const ids=r.m[7].filter(c=>c[0]<=bi).at(-1)?.[1]||[],change=controlView?'Corrected current':r.top&&!r.oldTop?'Gained Top':!r.top&&r.oldTop?'Lost Top':r.degree&&!r.oldDegree?'Gained degree Top':!r.degree&&r.oldDegree?'Lost degree Top':'Unchanged coverage';return`<tr><td><b>${h(r.p.name)}</b><br>${h(r.p.id)}<br>${h(labels[r.cohort])}${!/^(scale056-|grok075-)/.test(r.p.id)?`<br><a href="/developer/legacy-facts-098.html?model=${encodeURIComponent(r.p.id)}">Profile facts</a>`:''}${r.cohort==='holdout'?`<br><a href="/developer/holdout-review-103.html?model=${encodeURIComponent(r.p.id)}${controlView?'&arm=control':''}">Follow-up evidence</a>`:''}</td><td>${ids.length?ids.map(i=>h(d.careers[i][1])).join('<br>'):'No supported Top yet'}</td><td>${r.degree?'Yes':'Not yet'}</td><td>${Math.min(b,r.m[6])} follow-ups<br>${60+Math.min(b,r.m[6])} interest questions total<br><b>${change}</b>${b===24&&$('compare').checked?'<br>Before: '+r.m[8].map(i=>h(d.careers[i][1])).join(', '):''}</td></tr>`;}).join('');$('more').hidden=page>=rs.length;}
try{[d,directory]=await Promise.all([fetchCohortJSON('/developer/evidence-103.json.gz'),fetchCohortJSON('/developer/current-students-091.json.gz')]);const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(directory.rows.map(r=>r.id)))))].map(v=>v.toString(16).padStart(2,'0')).join('');if(hash!==d.directoryHash)throw Error('Model directory version mismatch. Reload the page.');document.querySelector('.eyebrow').textContent='RESEARCH 0.103 · LIVE FLOW UNCHANGED';document.querySelector('h1').textContent='Hybrid follow-ups · 60 + 24';$('budget').innerHTML=d.budgets.map((b,i)=>`<option value="${i}" ${b===24?'selected':''}>${b} follow-ups · ${60+b} interest questions total</option>`).join('');if(controlView){for(const s of d.summary){s.curves.targeted=s.curves.previous;s.changes=d.budgets.map(budget=>({budget,gainedTop:0,lostTop:0,gainedDegree:0,lostDegree:0}));}d.models=d.models.map(m=>{const c=m.slice();c[2]=m[4];c[3]=m[5];c[7]=m[9];c[6]=m[10];return c;});document.querySelector('h1').textContent='Current corrected matches · 60 + 24';$('compare').parentElement.style.display='none';document.querySelector('nav').insertAdjacentHTML('beforeend','<a href="/developer/fresh-start-095.html?study=103&budget=24">Hybrid comparison</a>');}$('compare').checked=!controlView;$('compare').nextSibling.textContent=' Compare architecture-corrected current block (dashed)';$('issue').insertAdjacentHTML('afterbegin','<option value="evaluable">Evaluable models</option>');$('issue').insertAdjacentHTML('beforeend','<option value="gainedTop">Gained Top</option><option value="lostTop">Lost Top</option><option value="lostDegree">Lost college Top</option>');if(controlView)for(const id of ['gainedTop','lostTop','lostDegree'])$('issue').querySelector('option[value="'+id+'"]')?.remove();$('issue').value='evaluable';const p=new URL(location.href).searchParams;if(d.budgets.includes(Number(p.get('budget')))&&p.has('budget'))$('budget').value=String(d.budgets.indexOf(Number(p.get('budget'))));if([...$('cohort').options].some(o=>o.value===p.get('cohort')))$('cohort').value=p.get('cohort');if([...$('group').options].some(o=>o.value===p.get('group')))$('group').value=p.get('group');else if($('cohort').value!=='all')$('group').value='first';if(p.get('model'))$('search').value=p.get('model');$('splits').parentElement.open=true;$('burden').parentElement.hidden=true;document.querySelector('nav').insertAdjacentHTML('beforeend','<a href="/developer/fresh-start-095.html?study=100&budget=24">Uncorrected research baseline ·0.100</a><a href="/developer/holdout-review-103.html'+(controlView?'?arm=control':'')+'">Original holdout review</a>');document.querySelector('nav').insertAdjacentHTML('beforeend','<a href="/developer/opening-review-103.html">Opening and loss review</a>');$('limits').innerHTML=d.limits.map(l=>`<li>${h(l)}</li>`).join('');render();for(const id of['budget','cohort','search','issue','compare','group'])$(id).addEventListener('input',()=>{if(id==='cohort'&&$('cohort').value!=='all')$('group').value='first';page=25;render();});$('more').onclick=()=>{page+=25;render();};}catch(e){$('plots').textContent=e.message;}
